class Solution {
public:
    int pos = 0;
    unordered_map<int, int> idx;

    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        pos = 0;
        idx.clear();
        for (int i = 0; i < (int)inorder.size(); i++) idx[inorder[i]] = i;
        return build(preorder, 0, (int)inorder.size() - 1);
    }

